# auto-cancel edit mode when navigating to a different WO (abandon unsaved edits)
try:
	if self.view.custom.isEditMode:
		_selIdx = self.props.selection.selectedRow
		_newId = None
		if _selIdx is not None and _selIdx >= 0 and self.props.data and _selIdx < len(self.props.data):
			try:
				_newId = int(self.props.data[_selIdx].get('WO_ID', 0))
			except:
				_newId = None
		_curId = None
		try:
			_curId = int(self.view.custom.selectedWoId)
		except:
			_curId = None
		if _newId is None or _newId != _curId:
			self.view.custom.isEditMode = False
			system.perspective.sendMessage('wo-editmode-ui', {}, scope='view')
			self.view.custom.isDirty = False
			self.view.custom.woHeaderSnapshot = None
			system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Edit auto-cancelled (navigated to WO ' + str(_newId) + ')'}, scope='session')
except:
	pass
system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'onSelectionChange fired'}, scope='session')
# Get selected row index
selIdx = self.props.selection.selectedRow
system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'selectedRow index = ' + str(selIdx)}, scope='session')
if selIdx is not None and selIdx >= 0:
	data = self.props.data
	if data and selIdx < len(data):
		row = data[selIdx]
		woId = row.get('WO_ID', 0)
		system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'From props.data: WO_ID=' + str(woId) + ' type=' + str(type(woId))}, scope='session')
		try:
			self.view.custom.selectedWoId = int(woId)
		except:
			self.view.custom.selectedWoId = 0
			system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'ERROR converting WO_ID'}, scope='session')
		self.view.custom.selectedShortWoId = str(row.get('Short_WO_Id', '')).strip()
		self.view.custom.selectedWoTitle = str(row.get('WO_Title', '')).strip()
		system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Set selectedWoId = ' + str(self.view.custom.selectedWoId)}, scope='session')
	else:
		system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'selIdx out of range or no data'}, scope='session')
# --- responsible-users summary (direct NQ, reliable) ---
try:
	_wo = self.view.custom.selectedWoId
	if _wo and int(_wo) > 0:
		_ds = system.db.runNamedQuery('Workmate/WO Responsible User/List', {'woId': int(_wo), 'includeRemoved': 0})
		_names = []
		for _r in range(_ds.getRowCount()):
			_su = _ds.getValueAt(_r, 'Short_User_Id')
			if _su: _names.append(unicode(_su).strip())
		self.view.custom.respUsersSummary = u', '.join(_names) if _names else u'(none)'
		system.perspective.sendMessage('debug-log', {'source':'WOMaint','message':'respUsers summary set: %s (%d)' % (self.view.custom.respUsersSummary, _ds.getRowCount())}, scope='session')
	else:
		self.view.custom.respUsersSummary = u'(none)'
except:
	import sys
	system.perspective.sendMessage('debug-log', {'source':'WOMaint','message':'respUsers summary ERROR: %s' % sys.exc_info()[1]}, scope='session')

