if hasattr(value, 'getRowCount'):
	headers = [str(value.getColumnName(i)) for i in range(value.getColumnCount())]
	rows = []
	for r in range(value.getRowCount()):
		row = {}
		for c in range(value.getColumnCount()):
			v = value.getValueAt(r, c)
			col = headers[c]
			if col == 'WO_ID':
				row[col] = int(v) if v is not None else 0
			else:
				row[col] = str(v).strip() if v is not None else ''
		# Add composite field for styled badge
		status = str(row.get('Status', '')).strip()
		shortId = str(row.get('Short_WO_Id', '')).strip()
		progId = row.get('Progress_Id', 0)
		try:
			progId = int(float(str(progId))) if (progId is not None and str(progId).strip() != '') else 0
		except:
			progId = 0
		_base = status + '|' + shortId if status else shortId
		# v16.13.0: 4th pipe part = HasPO for the WONumBadge v1.3.0 PO dot.
		# Defensive: column absent (Search NQ not yet updated) -> 0, no dot.
		_hasPO = row.get('HasPO', 0)
		try:
			_hasPO = 1 if int(float(str(_hasPO))) > 0 else 0
		except:
			_hasPO = 0
		row['WO_IdStyled'] = _base + '|' + str(progId) + '|' + str(_hasPO)
		try:
			if not self.view.custom.pgDiagDone:
				self.view.custom.pgDiagDone = True
				_hasPg = ('Progress_Id' in row)
				system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'LIST DIAG: Progress_Id present=' + str(_hasPg) + ' sample progId=' + str(progId) + ' for ' + str(row.get('Short_WO_Id',''))}, scope='session')
		except:
			pass
		rows.append(row)
	value = rows
if not value:
	value = []
self.view.custom.woListRecordCount = len(value)

# Auto-select row if navigated from Schedulex
try:
	pendingId = self.view.custom.pendingWoId
	if pendingId and int(pendingId) > 0:
		targetId = int(pendingId)
		for i, row in enumerate(value):
			if row.get('WO_ID', 0) == targetId:
				# Visual highlight
				# Visual highlight skipped (setting props.selection in transform locks table)
				# Set the SAME props that onSelectionChange sets
				self.view.custom.selectedWoId = targetId
				self.view.custom.selectedShortWoId = str(row.get('Short_WO_Id', '')).strip()
				self.view.custom.selectedWoTitle = str(row.get('WO_Title', '')).strip()
				system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Auto-selected row ' + str(i) + ' for WO_ID ' + str(targetId)}, scope='session')
				break
		# Clear pending regardless of match
		self.view.custom.pendingWoId = 0
except:
	pass


