# guard, which Designer saves kept re-baking as done - baked woId fired
# the Item NQ pre-startup, see 2026-07-14 log). Runs on every list
# refresh: keep the current selection if it is still in the (re)filtered
# list; otherwise select row 0. Immune to Designer-baked view.custom
# state - the PurchaseOrder fresh-view-reset lesson, applied structurally.
try:
	pendingNow = 0
	try:
		pendingNow = int(self.view.custom.pendingWoId or 0)
	except:
		pendingNow = 0
	if pendingNow <= 0:
		curId = 0
		try:
			curId = int(self.view.custom.selectedWoId or 0)
		except:
			curId = 0
		inList = False
		if curId > 0:
			for row in value:
				if row.get('WO_ID', 0) == curId:
					inList = True
					break
		if not inList and value and len(value) > 0:
			firstRow = value[0]
			self.view.custom.selectedWoId = firstRow.get('WO_ID', 0)
			self.view.custom.selectedShortWoId = str(firstRow.get('Short_WO_Id', '')).strip()
			self.view.custom.selectedWoTitle = str(firstRow.get('WO_Title', '')).strip()
			system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Reconcile: selected first WO_ID=' + str(firstRow.get('WO_ID', 0)) + ' (prev=' + str(curId) + ')'}, scope='session')
except:
	pass

return value

try:
	system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Item NQ fired, woId=' + str(self.view.custom.selectedWoId)}, scope='session')
