			headers = [str(value.getColumnName(i)) for i in range(value.getColumnCount())]
			row = {}
			for c in range(value.getColumnCount()):
				v = value.getValueAt(0, c)
				row[headers[c]] = v
			try:
				details = system.db.runNamedQuery('Workmate/Workorder Detail/Item', {'woId': self.view.custom.selectedWoId})
				if hasattr(details, 'getRowCount') and details.getRowCount() > 0:
					dHeaders = [str(details.getColumnName(i)) for i in range(details.getColumnCount())]
					for c in range(details.getColumnCount()):
						v = details.getValueAt(0, c)
						row[dHeaders[c]] = v
					pId = row.get('Progress_Id', '?')
					rId = row.get('Reason_Id', '?')
					fId = row.get('Fault_Id', '?')
					cId = row.get('Condition_Id', '?')
					system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Detail: Prog=' + str(pId) + ' Reason=' + str(rId) + ' Fault=' + str(fId) + ' Cond=' + str(cId)}, scope='session')
			except:
				system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Detail NQ failed'}, scope='session')
			for idField in ['Reason_Id', 'Fault_Id', 'Condition_Id', 'Progress_Id', 'Account_Id', 'Cost_Center_Id', 'Priority_Id', 'WO_Group_Id', 'WOC1_ID', 'WOC2_ID', 'WOC3_ID', 'Location_Id', 'Asset_ID', 'Company_ID', 'Supplier_ID_charge_To', 'Supplier_ID_Requested_By', 'Supplier_ID_Responsibility', 'User_ID_Responsibility', 'User_Id_Ack_by', 'User_Id_Approved_By', 'User_ID_ClosedBy', 'User_ID_CancelledBy']:
				if row.get(idField) is None:
					row[idField] = 0
			defaults = dict(row)
			# Supplementary lookups for display labels
			try:
				locId = int(float(str(defaults.get('Location_Id', 0) or 0)))
				if locId > 0:
					locDs = system.db.runQuery(
						"SELECT Short_Location_ID, Location_Title FROM Location WHERE Location_Id = " + str(locId),
						'TLSQL01_Workmate'
					)
					if hasattr(locDs, 'getRowCount') and locDs.getRowCount() > 0:
						defaults['Short_Location_ID'] = str(locDs.getValueAt(0, 0) or '').strip()
						defaults['Location_Title'] = str(locDs.getValueAt(0, 1) or '').strip()
				astId = int(float(str(defaults.get('Asset_ID', 0) or 0)))
				if astId > 0:
					astDs = system.db.runQuery(
						"SELECT Short_asset_Id, Asset_Title FROM Asset WHERE Asset_ID = " + str(astId),
						'TLSQL01_Workmate'
					)
					if hasattr(astDs, 'getRowCount') and astDs.getRowCount() > 0:
						defaults['Short_asset_Id'] = str(astDs.getValueAt(0, 0) or '').strip()
						defaults['Asset_Title'] = str(astDs.getValueAt(0, 1) or '').strip()
				if not defaults.get('Parent_Location_Hierarchy'):
					hDs = system.db.runQuery(
						"SELECT Parent_Location_Hierarchy FROM WO_N_Header WHERE WO_ID = " + str(self.view.custom.selectedWoId),
						'TLSQL01_Workmate'
					)
					if hasattr(hDs, 'getRowCount') and hDs.getRowCount() > 0:
						defaults['Parent_Location_Hierarchy'] = str(hDs.getValueAt(0, 0) or '')
			except Exception as ex:
				system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Supplement error: ' + str(ex)}, scope='session')
			self.view.custom.selectedWoData = defaults
			try:
				_progId = int(float(str(defaults.get('Progress_Id', 0))))
			except:
				_progId = 0
			self.view.custom.woProgressId = _progId
			system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'SYNC: woProgressId=' + str(_progId)}, scope='session')
			try:
				_st = defaults.get('Status')
				_st = str(_st).strip() if _st is not None else ''
				if _st != '':
					self.view.custom.woStatusCode = _st
			except:
				pass
			# --- reverse-derive Complete-within segment from stored Start/End span ---
			try:
				_sd = defaults.get('Request_Start_Date')
				_ed = defaults.get('Request_End_Date')
				_within = 'range'
				if _sd is not None and _ed is not None:
					_days = system.date.daysBetween(_sd, _ed)
					_months = system.date.monthsBetween(_sd, _ed)
					if _days == 1:
						_within = 'day'
					elif _days == 7:
						_within = 'week'
					elif _days == 14:
						_within = 'nextshut'
					elif _months == 1 and _days <= 31:
						_within = 'month'
					elif _months == 3 and _days <= 93:
						_within = '3month'
					else:
						_within = 'range'
				self.view.custom.woCompleteWithin = _within
			except:
				self.view.custom.woCompleteWithin = 'range'
			result = str(row.get('Short_WO_Id', '')).strip()
			system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Loaded WO: ' + result + ' | prog=' + str(_progId)}, scope='session')
			return result
	system.perspective.sendMessage('debug-log', {'source': 'WOMaint', 'message': 'Item NQ: no data returned'}, scope='session')
	return ''

