try:
	raw = str(raw)
	# Parse format: {(id)(shortId)(title)}{(id)(shortId)(title)}...
	parts = []
	i = 0
	while i < len(raw):
		if raw[i] == '{':
			# Find matching closing brace
			j = raw.index('}', i)
			block = raw[i+1:j]
			# block = (id)(shortId)(title)
			# Extract the title (third parenthesised group)
			segs = []
			k = 0
			while k < len(block):
				if block[k] == '(':
					m = block.index(')', k)
					segs.append(block[k+1:m])
					k = m + 1
				else:
					k += 1
			if len(segs) >= 3:
				parts.append(segs[2])
			i = j + 1
		else:
			i += 1
	return ' > '.join(parts) if parts else raw
except:
	return str(raw)

